h: 80px;\n    height: 80px;\n    margin: 0 auto 25px;\n    animation: udSpin 6s linear infinite;\n    filter: drop-shadow(0 4px 10px rgba(0, 40, 160, 0.35));\n  }\n  @keyframes udSpin { to { transform: rotate(360deg); } }\n  /* Title */\n  .ud-title {\n    font-size: clamp(32px, 7vw, 64px);\n    font-weight: 800;\n    color: #0a1f5c;\n    letter-spacing: 1px;\n    text-shadow: 0 4px 18px rgba(255, 255, 255, 0.7);\n    animation: udPulse 3s ease-in-out infinite;\n  }\n  @keyframes udPulse {\n    0%, 100% { transform: scale(1); }\n    50%      { transform: scale(1.04); }\n  }\n  /* Animated dots */\n  .ud-dots span {\n    display: inline-block;\n    animation: udDot 1.4s infinite;\n  }\n  .ud-dots span:nth-child(2) { animation-delay: .1s; }\n  .ud-dots span:nth-child(3) { animation-delay: .2s; }\n  .ud-dots span:nth-child(4) { animation-delay: .3s; }\n  .ud-dots span:nth-child(5) { animation-delay: .4s; }\n  .ud-dots span:nth-child(6) { animation-delay: .5s; }\n  .ud-dots span:nth-child(7) { animation-delay: .6s; }\n  .ud-dots span:nth-child(8) { animation-delay: .7s; }\n  @keyframes udDot {\n    0%, 60%, 100% { transform: translateY(0); opacity: .4; }\n    30%           { transform: translateY(-14px); opacity: 1; }\n  }\n  .ud-sub {\n    margin-top: 18px;\n    font-size: clamp(14px, 2.5vw, 18px);\n    font-weight: 300;\n    color: #0d2a7a;\n    min-height: 28px;\n  }\n  .ud-cursor { animation: udBlink 0.8s infinite; }\n  @keyframes udBlink { 50% { opacity: 0; } }\n</style>\n    <svg viewBox=\"0 0 24 24\" fill=\"#0047ff\" xmlns=\"http://www.w3.org/2000/svg\">\n      <path d=\"M19.14 12.94a7.07 7.07 0 0 0 .06-.94 7.07 7.07 0 0 0-.06-.94l2.03-1.58a.5.5 0 0 0 .12-.64l-1.92-3.32a.5.5 0 0 0-.61-.22l-2.39.96a7.03 7.03 0 0 0-1.62-.94l-.36-2.54a.5.5 0 0 0-.5-.42h-3.84a.5.5 0 0 0-.5.42l-.36 2.54c-.59.24-1.13.56-1.62.94l-2.39-.96a.5.5 0 0 0-.61.22L2.71 8.84a.5.5 0 0 0 .12.64l2.03 1.58a7.07 7.07 0 0 0-.06.94c0 .32.02.63.06.94L2.83 14.52a.5.5 0 0 0-.12.64l1.92 3.32c.13.22.39.31.61.22l2.39-.96c.5.38 1.03.7 1.62.94l.36 2.54c.04.24.25.42.5.42h3.84c.25 0 .46-.18.5-.42l.36-2.54c.59-.24 1.13-.56 1.62-.94l2.39.96c.22.09.48 0 .61-.22l1.92-3.32a.5.5 0 0 0-.12-.64l-2.03-1.58ZM12 15.5A3.5 3.5 0 1 1 12 8.5a3.5 3.5 0 0 1 0 7Z\"/>\n    </svg>\n    <h1>\n      Under Development........\n    </h1>\n    <p>|</p>', 'Blog', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-11-12 18:08:18', '2026-11-12 18:08:18', '', 15, 'http://localhost/portfolio01/?p=63', 0, 'revision', '', 0),
